import { Object3D, Mesh, PlaneGeometry, Color } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import { gsap } from 'gsap';
import { createMSDFText } from '@/text';

export default function createNode(config, ctx) {
    const {
        assets = {},
        textContent = '',
        position = [0, 0, 0],
        rotation = [0, 0, 0],
        scale = [1, 1, 1],
        cinematicPrimitives = []
    } = config;

    // Root object
    const root = new Object3D();

    // --------------------
    // Background plane
    // --------------------
    const bgTexture = ctx.textureLoader.load(assets.imageUrl);
    // Preserve aspect of the source image (512 × 320 → 1.6 × 1)
    const bgGeometry = new PlaneGeometry(1.6, 1);
    const bgMaterial = new MeshBasicNodeMaterial();
    bgMaterial.map = texture(bgTexture);
    const bgMesh = new Mesh(bgGeometry, bgMaterial);
    bgMesh.name = 'background';
    root.add(bgMesh);

    // --------------------
    // MSDF Text
    // --------------------
    const inkColor = new Color('#16161d');
    const textMesh = createMSDFText(textContent, {
        atlas: ctx.fontAtlas,
        color: inkColor,
        // size expressed in scene units; adjust as needed
        size: 0.13
    });
    // Slightly in front of the background to avoid z‑fighting
    textMesh.position.set(0, 0, 0.01);
    textMesh.name = 'label';
    root.add(textMesh);

    // --------------------
    // Apply cinematic primitives (none expected for this node)
    // --------------------
    for (const primitive of cinematicPrimitives) {
        const fn = ctx.primitives[primitive.name];
        if (typeof fn === 'function') {
            fn(root, primitive.params);
        }
    }

    // --------------------
    // Transform
    // --------------------
    root.position.fromArray(position);
    root.rotation.fromArray(rotation);
    root.scale.fromArray(scale);

    // --------------------
    // Event handlers placeholder
    // --------------------
    root.userData.handlers = {};

    // --------------------
    // Cleanup
    // --------------------
    root.userData.cleanup = () => {
        // Dispose background resources
        if (bgTexture) bgTexture.dispose();
        if (bgGeometry) bgGeometry.dispose();
        if (bgMaterial) bgMaterial.dispose();

        // Dispose text resources
        if (textMesh) {
            if (textMesh.geometry) textMesh.geometry.dispose();
            if (textMesh.material) textMesh.material.dispose();
        }

        // Kill any GSAP timelines that may have been created
        gsap.globalTimeline.clear();
    };

    return root;
}
